<?php require_once __DIR__.'/_base.php'; $title='Notifications'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php if(isset($_GET['read'])){$pdo->prepare('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?')->execute([(int)$_GET['read'],$u['id']]);redirect('notifications.php');}$st=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC');$st->execute([$u['id']]);?><h2>Notifications</h2><div class="service-card p-3"><?php foreach($st->fetchAll() as $n):?><a class="d-block text-decoration-none text-dark border-bottom p-3 <?=!$n['is_read']?'bg-light':''?>" href="?read=<?=$n['id']?>"><b><?=e($n['title'])?></b><p class="mb-1 text-secondary"><?=e($n['message'])?></p><small><?=e($n['created_at'])?></small></a><?php endforeach;?></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>